#include <bits/stdc++.h>using namespace std; int main(){    ios::sync_with_stdio(false);    cin.tie(NULL);     int t;    cin >> t;     while(t--){        long long w, h;        cin >> w >> h;         long long ans = 0;         // Bottom side (y = 0)        int k;        cin >> k;        vector<long long> v(k);        for(int i = 0; i < k; i++) cin >> v[i];         ans = max(ans, (v.back() - v.front()) * h);         // Top side (y = h)        cin >> k;        v.resize(k);        for(int i = 0; i < k; i++) cin >> v[i];         ans = max(ans, (v.back() - v.front()) * h);         // Left side (x = 0)        cin >> k;        v.resize(k);        for(int i = 0; i < k; i++) cin >> v[i];         ans = max(ans, (v.back() - v.front()) * w);         // Right side (x = w)        cin >> k;        v.resize(k);        for(int i = 0; i < k; i++) cin >> v[i];         ans = max(ans, (v.back() - v.front()) * w);         cout << ans << "\n";    }}